"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["59378"],{49259(e){e.exports=JSON.parse('{"id":"V4-144","slug":"title-insurance","term":"Title Insurance","also_known_as":[],"difficulty":"Intermediate","definition":"Title insurance is a type of insurance that protects property buyers and mortgage lenders against financial loss from defects in the legal ownership, or title, of a property that were not found before the purchase.","explanation":["Title defects can include errors in public records, undisclosed liens or debts attached to the property, forged documents, unknown heirs claiming ownership or boundary disputes.","Title insurance is especially common in the United States, where it is usually required by mortgage lenders. There are two main types. A lender\u2019s policy protects the lender\u2019s interest in the property. An owner\u2019s policy protects the buyer. Both are typically paid for with a single premium at the time of purchase and last as long as the insured has an interest in the property.","For example, if after buying a home, the owner discovers an unpaid debt from a previous owner secured against the property, title insurance could cover the cost of resolving the claim.","Before issuing a policy, the title company searches public records to identify problems. Title insurance is less common in the United Kingdom, Australia and many other countries, where government-guaranteed land registration systems provide greater certainty of ownership, although it is used in some situations, such as to cover specific known risks."],"note":"","total":1725,"prev":{"slug":"time-weighted-return","term":"Time-Weighted Return"},"next":{"slug":"tokenization","term":"Tokenization"}}')}}]);